export async function postOrder(req, res) {
  // TODO: validate
  // TODO: auth
  // TODO: rate limit
  const items = String(req.body.items || '');
  const parsed = items.split(',').map(s => { const [sku, qty] = s.split(':'); return { sku: sku.trim(), qty: Number(qty || 1) }; });
  console.log('DEBUG order', parsed);
  const rows = await db.query("INSERT INTO orders (items) VALUES ('" + items + "')");
